{"text":"[Reading 43 lines from start (total: 43 lines, 0 remaining)]\n\n\n\"\"\"\nData Ingestion Worker - ดึงข้อมูลทุก 1 วิ\nBinance, Bitkub, News, Funding, On-chain\n\"\"\"\nimport asyncio\nimport websockets\nimport json\nimport asyncpg\nimport redis\nfrom datetime import datetime\n\nclass DataIngestionWorker:\n    def __init__(self):\n        self.redis = redis.Redis(host='localhost', port=6379, decode_responses=True)\n        \n    async def binance_ws(self):\n        uri = \"wss://stream.binance.com:9443/ws/btcusdt@trade\"\n        async with websockets.connect(uri) as ws:\n            while True:\n                msg = await ws.recv()\n                data = json.loads(msg)\n                # Push to Redis + Timescale\n                self.redis.publish(\"market:btcusdt\", json.dumps(data))\n                print(f\"[{datetime.now()}] BTC Price: {data['p']}\")\n                \n    async def funding_rate_poller(self):\n        while True:\n            # Mock funding rate\n            funding = {\"symbol\": \"BTCUSDT\", \"fundingRate\": 0.0001, \"time\": datetime.now().isoformat()}\n            self.redis.set(\"funding:btcusdt\", json.dumps(funding))\n            await asyncio.sleep(60)\n    \n    def run(self):\n        print(\"📡 Data Ingestion Worker Started - 1s interval\")\n        loop = asyncio.get_event_loop()\n        loop.run_until_complete(asyncio.gather(\n            self.binance_ws(),\n            self.funding_rate_poller()\n        ))\n\nif __name__ == \"__main__\":\n    DataIngestionWorker().run()\n\n[executed on device: 10_3_6_9 (85294689-03d5-431e-abd5-9e27d4c94814)]"}